// Izvuci AI tekst iz Responses API formata
const aiContent = $json.output?.[0]?.content?.[0]?.text || '';

// Lead podaci dolaze iz 'Take 1 Lead' nodea (pre OpenAI)
const lead = $('Take 1 Lead').item.json;

let parsed;
try {
  const cleaned = aiContent.replace(/^```json\n?|^```\n?|\n?```$/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    subject: `AI Recepcioner za ${lead['Naziv firme'] || 'vašu ordinaciju'}`,
    body: aiContent
  };
}

return {
  row_number:    lead.row_number,
  email:         lead['Email'] || '',
  company:       lead['Naziv firme'] || '',
  category:      lead['Kategorija'] || '',
  city:          lead['Grad'] || '',
  phone:         lead['Telefon'] || '',
  email_subject: parsed.subject,
  email_body:    parsed.body
};

const body  = $json.email_body || '';
const email = $json.email || '';
const logo  = 'https://res.cloudinary.com/drpzkf5m5/image/upload/v1780351890/horizenaidesnologg_zyucv2.png';

const paragraphs = body
  .split('\n')
  .filter(l => l.trim())
  .map(l => `<p style="margin:0 0 16px;font-size:15px;line-height:1.7;color:#1a1a1a;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif">${l.trim()}</p>`)
  .join('');

const html = `<!DOCTYPE html>
<html lang="sr">
<head>
  <meta charset="UTF-8">
  <meta http-equiv="Content-Type" content="text/html; charset=UTF-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <meta name="color-scheme" content="light">
  <style>
    @media only screen and (max-width:600px){
      .hdr{padding:14px 24px!important}
      .bd{padding:24px 24px 4px!important}
      .ctaw{padding:8px 24px 28px!important}
      .ftr{padding:16px 24px!important}
    }
    @media (prefers-color-scheme:dark){
      .hdr{background:#0a0a0a!important}
    }
    [data-ogsc] .hdr{background:#0a0a0a!important}
  </style>
</head>
<body style="margin:0;padding:20px;background:#ffffff;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif">

  <div style="border:1px solid rgba(124,106,255,0.3);border-radius:14px;overflow:hidden">

    <!-- Header -->
    <div class="hdr" style="background:#0a0a0a;padding:3px 32px">
      <img src="${logo}" alt="Horizen AI" width="150"
           style="width:150px;height:auto;display:block">
    </div>

    <!-- Accent -->
    <div style="height:3px;background:linear-gradient(90deg,#7c6aff,#a78bfa)"></div>

    <!-- Body -->
    <div class="bd" style="background:#fafafa;padding:32px 36px 4px">
      ${paragraphs}
    </div>

    <!-- CTA -->
    <div class="ctaw" style="background:#fafafa;padding:12px 36px 32px">
      <a href="https://horizen.rs"
         style="display:inline-block;background:#7c6aff;color:#ffffff;text-decoration:none;padding:13px 26px;border-radius:9px;font-size:15px;font-weight:600;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif">
        Pogledaj kako funkcioniše →
      </a>
    </div>

    <!-- Footer -->
    <div class="ftr" style="background:#f0f0f0;border-top:1px solid #e0e0e0;padding:18px 36px">
      <p style="font-size:12px;color:#aaa;margin:0;line-height:1.9;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif">
        <strong style="color:#666">Horizen AI</strong><br>
        <a href="mailto:matija@horizen.rs" style="color:#aaa;text-decoration:none">matija@horizen.rs</a>
        &nbsp;·&nbsp;
        <a href="https://horizen.rs" style="color:#aaa;text-decoration:none">horizen.rs</a>
        &nbsp;·&nbsp;
        <a href="https://horizen.rs/unsubscribe?email=${encodeURIComponent(email)}" style="color:#aaa;text-decoration:none">Matija Radulović</a>
      </p>
    </div>

  </div>

</body>
</html>`;

return { ...$json, email_body_html: html };

const log = {
  timestamp: new Date().toISOString(),
  email:   $json.email,
  company: $json.company,
  subject: $json.email_subject,
  status:  'draft_created'
};
console.log('DRAFT CREATED:', JSON.stringify(log));
return { success: true, ...log };
